create or replace function suggest_substitutes_for_day_v3(p_date date default current_date) returns table(absence_lesson_id uuid,period smallint,class_id uuid,class_name text,subject text,candidate_user_id uuid,candidate_name text,qualified boolean,duty boolean,weekly_load bigint,monthly_load bigint,rank_score numeric,reason text) language sql stable security definer set search_path=public as $$with tenant as(select current_tenant_code() code),el as(select al.*,cc.id course_id from absence_lessons al cross join tenant t left join lateral(select c.id from course_catalog c where c.active and lower(c.name)=lower(al.subject) limit 1)cc on true left join substitute_assignments sa on sa.absence_lesson_id=al.id where al.institution_code=t.code and al.lesson_date=p_date and sa.id is null),pool as(select el.id lesson_id,p.user_id,exists(select 1 from teacher_duty_assignments d where d.teacher_id=p.user_id and d.duty_date=p_date) duty,el.course_id,el.teacher_id,el.period from el join profiles p on p.role='teacher'),eligible as(select x.*,exists(select 1 from teacher_course_assignments a join class_course_requirements r on r.id=a.class_course_requirement_id where a.teacher_id=x.user_id and r.course_id=x.course_id) qualified,(select count(*) from substitute_assignments s join absence_lessons l on l.id=s.absence_lesson_id where s.substitute_user_id=x.user_id and l.lesson_date>=date_trunc('week',p_date)::date and l.lesson_date<(date_trunc('week',p_date)+interval '7 days')::date) weekly_load,(select count(*) from substitute_assignments s join absence_lessons l on l.id=s.absence_lesson_id where s.substitute_user_id=x.user_id and l.lesson_date>=date_trunc('month',p_date)::date and l.lesson_date<(date_trunc('month',p_date)+interval '1 month')::date) monthly_load from pool x where x.user_id<>x.teacher_id and not exists(select 1 from absences a where a.institution_code=current_tenant_code() and a.teacher_id=x.user_id and a.absence_date=p_date and a.status<>'resolved') and not exists(select 1 from teacher_unavailability u where u.teacher_id=x.user_id and u.weekday=extract(isodow from p_date)::smallint and u.period=x.period and u.active) and not exists(select 1 from teacher_schedule ts where ts.active and ts.teacher_id=x.user_id and ts.weekday=extract(isodow from p_date)::smallint and ts.period=x.period) and not exists(select 1 from substitute_assignments s join absence_lessons l on l.id=s.absence_lesson_id where s.substitute_user_id=x.user_id and l.lesson_date=p_date and l.period=x.period)),ranked as(select e.*,row_number() over(partition by lesson_id order by case when duty and qualified then 0 when qualified then 1 when duty then 2 else 3 end,weekly_load,monthly_load,user_id) rn,(case when duty and qualified then 0 when qualified then 100 when duty then 200 else 300 end+weekly_load*10+monthly_load)::numeric rank_score from eligible e) select el.id,el.period,el.class_id,el.class_name,el.subject,r.user_id,p.full_name,r.qualified,r.duty,r.weekly_load,r.monthly_load,r.rank_score,concat(case when r.qualified then 'Ders yeterliliği var' else 'Ders yeterliliği doğrulanamadı' end,' · ',case when r.duty then 'nöbetçi' else 'uygun öğretmen' end,' · haftalık yük ',r.weekly_load) from el join ranked r on r.lesson_id=el.id and r.rn<=10 join profiles p on p.user_id=r.user_id order by el.period,el.class_name,r.rn$$;
create or replace function assign_substitutes_for_day_v3(p_date date default current_date) returns integer language plpgsql security definer set search_path=public as $$declare x record;n int:=0;begin if not is_manager_or_admin() then raise exception 'NOT_AUTHORIZED';end if;for x in select distinct on(absence_lesson_id) * from suggest_substitutes_for_day_v3(p_date) order by absence_lesson_id,rank_score,candidate_user_id loop insert into substitute_assignments(absence_lesson_id,substitute_user_id,assigned_by,institution_code) values(x.absence_lesson_id,x.candidate_user_id,auth.uid(),current_tenant_code()) on conflict do nothing;if found then n:=n+1;end if;end loop;return n;end$$;